{
  "findings": [
    {
      "check_id": "CKV2_AWS_22",
      "title": "Ensure an IAM User does not have access to the console",
      "resource": "aws_iam_user.fp3-deny-iam-user",
      "severity": "MEDIUM",
      "explanation": "The IAM user does not explicitly deny console access. This could allow unintended access to the AWS Management Console, which increases the attack surface."
    }
  ],
  "patched_code": "resource \"aws_iam_user\" \"fp3-deny-iam-user\" {\n  name = \"fp3-deny-iam-user\"\n  path = \"/\"\n\n  tags = {\n    \"forbid_console_access\" = \"true\"\n  }\n\n  permissions_boundary = \"arn:aws:iam::aws:policy/AWSServiceRoleForSupport\"\n}\n",
  "fix_summary": "Added a permissions boundary to restrict console access and tagged the user for clarity."
}
